                arabicText = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\\nتَحَصَّنْتُ بِذِي الْمُلْكِ وَالْمَلَكُوتِ، وَاعْتَصَمْتُ بِذِي الْعِزَّةِ وَالْجَبَرُوتِ، وَتَوَكَّلْتُ عَلَى الْمَلِكِ الْحَيِّ الْقَيُّومِ الَّذِي لَا يَمُوتُ، دَخَلْتُ فِي حِرْزِ اللَّهِ، دَخَلْتُ فِي حِفْظِ اللَّهِ، وَدَخَلْتُ فِي أَمَانِ اللَّهِ، بِحَقِّ كٓهٰيٰعٓصٓ كُفِيتُ، وَبِـحٰمٓ عٓسٓقٓ حُمِيتُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ. وَقَالَ مُوسَىٰ إِنِّي عُذْتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ الْحِسَابِ.\\n\\nاللَّهُمَّ بِسَطْوَةِ جَبَرُوتِ قَهْرِكَ، وَبِسُرْعَةِ إِغَاثَةِ نَصْرِكَ، وَبِغَيْرَتِكَ لِانْتِهَاكِ حُرُمَاتِكَ، وَبِحِمَايَتِكَ لِمَنِ احْتَمَىٰ بِآيَاتِكَ، نَسْأَلُكَ يَا اللَّهُ، يَا سَمِيعُ، يَا قَرِيبُ، يَا مُجِيبُ، يَا سَرِيعُ، يَا مُنْتَقِمُ، يَا جَبَّارُ، يَا قَهَّارُ، يَا شَدِيدَ الْبَطْشِ، يَا مَنْ لَا يُعْجِزُهُ قَهْرُ الْجَبَابِرَةِ، وَلَا يَعْظُمُ عَلَيْهِ هَلَاكُ الْمُتَمَرِّدَةِ مِنَ الْمُلُوكِ وَالْأَكَاسِرَةِ",
                tajwidTags = "بِسْمِ اللَّهِ [l[ال]][l[رَّ]]حْمَٰنِ [l[ال]][p[رَّحِيمِ]]\\nتَحَ[g[صَّ]][f[نتُ]] بِذِي الْمُلْكِ وَالْمَلَكُوتِ، وَ[l[اعْ]]تَصَمْتُ بِذِي الْعِ[g[زَّ]]ةِ وَالْجَبَرُوتِ، وَتَوَ[g[كَّ]]لْتُ عَلَى الْمَلِكِ الْحَيِّ [p[الْقَيُّومِ]] الَّذِي لَا [p[يَمُوتُ]]، دَخَلْتُ فِي حِرْزِ اللَّهِ، دَخَلْتُ فِي حِ[q[فْ]]ظِ اللَّهِ، وَدَخَلْتُ فِي [o[أَمَانِ]] اللَّهِ، بِحَ[g[قِّ]] [o[كٓ]][o[هٰ]][o[يٰ]][o[عٓ]][o[صٓ]] كُفِيتُ، وَبِـ[o[حٰ]][o[مٓ]] [o[عٓ]][o[سٓ]][o[قٓ]] حُمِيتُ، وَلَا حَوْلَ وَلَا قُوَّةَ [o[إِلَّا]] بِاللَّهِ الْعَلِيِّ [p[الْعَظِيمِ]]. وَقَالَ مُوسَىٰ [g[إِنِّي]] عُذْتُ بِرَ[g[بِّي]] وَرَ[g[بِّ]][f[كُم]] [f[مِّن]] كُ[g[لِّ]] مُتَكَ[g[بِّ]][u[رٍ]] [u[لَّا]] يُؤْمِنُ بِيَوْمِ [p[الْحِسَابِ]].\\n\\n[g[اللَّ]]هُمَّ بِسَ[q[طْ]]وَةِ جَبَرُوتِ قَهْرِكَ، وَبِسُرْعَةِ [o[إِغَاثَةِ]] [f[نَصْ]]رِكَ، وَبِغَيْرَتِكَ [l[لِانْ]]تِهَاكِ حُرُمَاتِكَ، وَبِحِمَايَتِكَ [l[لِمَنِ]] [l[احْ]]تَمَىٰ [o[بِآيَاتِكَ]]، [l[نَسْ]]أَلُكَ يَا اللَّهُ، يَا سَمِيعُ، يَا قَرِيبُ، يَا مُجِيبُ، يَا سَرِيعُ، يَا [f[مُنتَ]][q[قِ]]مُ، يَا جَبَّارُ، يَا قَهَّارُ، يَا شَدِيدَ [p[الْبَطْشِ]]، يَا [u[مَن]] [u[لَّا]] يُعْجِزُهُ قَهْرُ الْجَبَابِرَةِ، وَلَا يَعْظُمُ عَلَيْهِ هَلَاكُ الْمُتَمَ[u[رِّ]]دَةِ مِنَ الْمُلُوكِ [p[وَالْأَكَاسِرَةِ]]",
                transliteration = "Bismillāhir-raḥmānir-raḥīm. Taḥaṣṣantu bidzil-mulki wal-malakūt, wa‘taṣamtu bidzil-‘izzati wal-jabarūt, wa tawakkaltu ‘alal-malikil-ḥayyil-qayyūmil-ladzī lā yamūt, dakhaltu fī ḥirzillāh, dakhaltu fī ḥifẓillāh, wa dakhaltu fī amānillāh, bi-ḥaqqi Kāf-Hā-Yā-‘Aīn-Ṣād kufīt, wa bi-Ḥā-Mīm-‘Aīn-Sīn-Qāf ḥumīt, wa lā ḥaula wa lā quwwata illā billāhil-‘aliyyil-‘aẓīm. Wa qāla Mūsā innī ‘udztu bi rabbī wa rabbikum ming kulli mutakabbiril lā yu’minu bi yaumil-ḥisāb.\\n\\nAllāhumma bi-saṭwati jabarūti qahrik, wa bi-sur‘ati ighātsati naṣrik, wa bi-ghairatika lintihāki ḥurumātik, wa bi-ḥimāyatika limaniḥtamā bi-āyātik, nas’aluka yā Allāh, yā Samī‘, yā Qarīb, yā Mujīb, yā Sarī‘, yā Mungtaqim, yā Jabbār, yā Qahhār, yā Syadīdal-baṭsy, yā mal lā yu‘jizuhū qahrul-jabābirah, wa lā ya‘ẓumu ‘alaihi halākul-mutamarridati minal-mulūki wal-akāsirah.",
                translationId = "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang. Aku berbenteng dengan Dzat Pemilik kerajaan dan malakut, aku berpegang teguh pada Pemilik keagungan dan kekuasaan mutlak (jabarut), dan aku bertawakal kepada Dzat Raja Yang Mahahidup lagi Maha Mengurus yang tidak pernah mati. Aku masuk ke dalam benteng Allah, aku masuk ke dalam penjagaan Allah, dan aku masuk ke dalam keamanan suaka Allah. Demi hak kebenaran Kaf-Ha-Ya-'Ain-Shad aku dicukupi, dan demi Ha-Mim-'Ain-Sin-Qaf aku dilindungi, serta tiada daya dan upaya melainkan dengan pertolongan Allah Yang Mahatinggi lagi Mahaagung. Dan berkata Musa: 'Sesungguhnya aku berlindung kepada Tuhanku dan Tuhanmu dari setiap orang yang menyombongkan diri yang tidak beriman kepada hari perhitungan' (QS. Ghafir: 27).\\n\\nYa Allah, demi keperkasaan kekuasaan penundukan-Mu, demi kecepatan pertolongan kemenangan-Mu, demi kecemburuan-Mu terhadap pelanggaran kehormatan-Mu, dan demi perlindungan-Mu bagi siapa yang berlindung dengan ayat-ayat-Mu...",
                translationEn = "In the name of Allah, the Entirely Merciful, the Especially Merciful. I fortify myself with the Owner of sovereignty and the unseen kingdom, and I take refuge in the Owner of might and omnipotence, and I rely upon the Ever-Living, the Sustainer who never dies. I have entered the fortress of Allah, the preservation of Allah, and the sanctuary of Allah. By the reality of Kaf-Ha-Ya-'Ayn-Sad I am sufficed, and by Ha-Mim-'Ayn-Sin-Qaf I am protected, and there is no power nor might except with Allah the Most High, the Supreme. And Moses said, 'Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account.' (QS. Ghafir: 27)...",
                repeatCount = 1,
                sourceNote = "Hizib An-Nashr Al-Imam Abul Hasan Asy-Syadzili, Majmu' Syarif",
                fadhilah = "Benteng pembuka benteng gaib, melumpuhkan tipu daya musuh yang hendak menindas dan menghancurkan hak kaum beriman."
