                arabicText = "اللَّهُمَّ بَدِّدْ شَمْلَهُمْ، اللَّهُمَّ فَرِّقْ جَمْعَهُمْ، اللَّهُمَّ أَقْلِلْ عَدَدَهُمْ، اللَّهُمَّ فُلَّ حَدَّهُمْ، اللَّهُمَّ اجْعَلِ الدَّائِرَةَ عَلَيْهِمْ، اللَّهُمَّ أَرْسِلِ الْعَذَابَ إِلَيْهِمْ، اللَّهُمَّ أَخْرِجْهُمْ عَنْ دَائِرَةِ الْحِلْمِ، وَاسْلُبْهُمْ مَدَدَ الْإِمْهَالِ، وَغُلَّ أَيْدِيَهُمْ إِلَىٰ أَعْنَاقِهِمْ وَأَرْجُلَهُمْ، وَارْبُطْ عَلَىٰ قُلُوبِهِمْ، وَلَا تُبَلِّغْهُمُ الْآَمَالَ",
                tajwidTags = "[g[اللَّ]]هُمَّ بَدِّ[q[دْ]] شَمْلَهُمْ، [g[اللَّ]]هُمَّ فَرِّ[q[قْ]] جَمْعَهُمْ، [g[اللَّ]]هُمَّ [q[أَقْ]]لِلْ عَدَدَهُمْ، [g[اللَّ]]هُمَّ فُ[g[لَّ]] حَ[g[دَّ]]هُمْ، [g[اللَّ]]هُمَّ [l[ا]][q[جْ]]عَلِ [l[الدَّ]][o[ائِرَةَ]] عَلَيْهِمْ، [g[اللَّ]]هُمَّ [o[أَرْسِلِ]] الْعَذَابَ [o[إِلَيْهِمْ]]، [g[اللَّ]]هُمَّ [o[أَخْرِ]][q[جْ]]هُمْ عَنْ دَ[o[ائِرَةِ]] الْحِلْمِ، وَ[l[اسْ]]لُ[q[بْ]]هُمْ مَدَدَ الْإِمْهَالِ، وَغُ[g[لَّ]] [o[أَيْدِيَهُمْ]] [o[إِلَىٰ]] [o[أَعْنَاقِهِمْ]] [o[وَأَرْجُلَهُمْ]]، وَ[l[ارْ]][q[بُطْ]] عَلَىٰ قُلُوبِهِمْ، وَلَا تُبَلِّ[q[غْ]]هُمُ [p[الْآَمَالَ]]",
                transliteration = "Allāhumma baddid syamlahum, Allāhumma farriq jam‘ahum, Allāhumma aqlil ‘adadahum, Allāhumma fulla ḥaddahum, Allāhummāj-‘alid-dā’irata ‘alaihim, Allāhumma arsilil-‘adzāba ilaihim, Allāhumma akhrijhum ‘an dā’iratil-ḥilm, waslub-hum madadad-im-hāl, wa ghulla aidiyahum ilā a‘nāqihim wa arjulahum, warbuṭh ‘alā قulūbihim, wa lā tuballigh-humul-āmāl.",
                translationId = "Ya Allah cerai-beraikanlah persatuan mereka, ya Allah pecah-belahkanlah perkumpulan mereka, ya Allah sedikitkanlah jumlah mereka, ya Allah tumpulkanlah ketajaman senjata mereka, ya Allah timpakanlah lingkaran kehancuran atas mereka, ya Allah kirimkanlah azab kepada mereka, ya Allah keluarkanlah mereka dari lingkaran santun-Mu, cabutlah dari mereka pertolongan penangguhan, belenggulah tangan-tangan dan kaki-kaki mereka ke leher-leher mereka, kunci matilah hati mereka, dan janganlah Engkau sampaikan angan-angan mereka.",
